// Intro Splash Controller: "O" with Eye Inside (Blink In & Blink Out)

export class IntroSplash {
  constructor() {
    this.splashEl = document.getElementById('intro-splash');
    this.appEl = document.getElementById('app');
    this.skipBtn = document.getElementById('skip-splash-btn');
    this.timer = null;
    this.hasDismissed = false;
  }

  init() {
    if (!this.splashEl) return;

    // Check if user has already visited in this session to allow quick reload, but always play on fresh start
    if (this.skipBtn) {
      this.skipBtn.addEventListener('click', () => this.dismiss());
    }

    // Auto dismiss after the eye has completed its blinking in and out sequence (~3 seconds)
    this.timer = setTimeout(() => {
      this.dismiss();
    }, 2800);
  }

  dismiss() {
    if (this.hasDismissed) return;
    this.hasDismissed = true;
    if (this.timer) clearTimeout(this.timer);

    if (this.splashEl) {
      this.splashEl.classList.add('fade-out');
      setTimeout(() => {
        this.splashEl.style.display = 'none';
      }, 800);
    }

    if (this.appEl) {
      this.appEl.classList.remove('app-hidden');
    }
  }

  replay() {
    this.hasDismissed = false;
    if (this.splashEl) {
      this.splashEl.style.display = 'flex';
      this.splashEl.classList.remove('fade-out');
    }
    if (this.appEl) {
      this.appEl.classList.add('app-hidden');
    }

    this.timer = setTimeout(() => {
      this.dismiss();
    }, 2800);
  }
}
